return {
  reduce: {
    hook: "incomingDamage", damageSource: "entity", timing: "postMitigation",
    async promptOnPlayer(H, actor) {
      const max = H.resource.focusCount(actor);
      if (max <= 0) return false;
      const choice = await H.ask.form({
        title: "Forewarned",
        bodyHtml: "Spend Focus to reduce incoming damage.",
        fields: [{ type: "number", name: "spend", label: "Spend Focus", min: 0, max, value: 0 }],
      });
      const spend = Math.max(0, Math.min(max, choice?.spend ?? 0));
      return spend > 0 ? { spend } : false;
    },
    async applyOnGM(H, actor, ctx, choice) {
      await H.resource.adjust(actor, { focus: -choice.spend });
      return { damageValue: Math.max(0, ctx.damageValue - choice.spend), note: `Forewarned: -${choice.spend}` };
    },
  },
};
